<?php ob_start(); ?>
<h1><?= esc($title) ?></h1><p class="muted">Updates affect future selections. Inactive records remain for historical process records.</p>
<?php if (session()->getFlashdata('error')): ?><p class="error"><?= esc(session()->getFlashdata('error')) ?></p><?php endif ?><?php if (session()->getFlashdata('message')): ?><p><?= esc(session()->getFlashdata('message')) ?></p><?php endif ?>
<section><h2 id="form-title">Add record</h2><form method="post" action="<?= site_url('admin/master-data/'.$kind) ?>" id="edit-form"><?= csrf_field() ?><input type="hidden" name="id" id="record-id"><?php foreach ($fields as $field => $label): ?><label><?= esc($label) ?> <?php if ($field === 'sector_id'): ?><select name="sector_id" id="field-sector_id" required><option value="">Choose sector</option><?php foreach ($sectors as $sector): ?><option value="<?= (int)$sector['id'] ?>"><?= esc($sector['name']) ?></option><?php endforeach ?></select><?php else: ?><input name="<?= esc($field) ?>" id="field-<?= esc($field) ?>" <?= $field === 'batch_qty' ? 'type="number" min="0"' : 'type="text"' ?> required><?php endif ?></label> &nbsp;<?php endforeach ?><button>Save</button><button type="button" onclick="resetForm()">Clear</button></form></section>
<section><table><thead><tr><th>ID</th><?php foreach ($fields as $field => $label): ?><th><?= esc($label) ?></th><?php endforeach ?><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= (int)$row['id'] ?></td><?php foreach ($fields as $field => $label): ?><td><?= esc($field === 'sector_id' ? ($row['sector_name'] ?? $row[$field] ?? '') : ($row[$field] ?? '')) ?></td><?php endforeach ?><td class="<?= $row['status'] === 'active' ? '' : 'inactive' ?>"><?= esc($row['status']) ?></td><td><button type="button" onclick='editRecord(<?= json_encode($row, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP) ?>)'>Edit</button> <form class="inline" method="post" action="<?= site_url('admin/master-data/'.$kind.'/'.$row['id'].'/toggle') ?>"><?= csrf_field() ?><button><?= $row['status'] === 'active' ? 'Deactivate' : 'Reactivate' ?></button></form></td></tr><?php endforeach ?></tbody></table></section>
<script>function resetForm(){document.getElementById('edit-form').reset();document.getElementById('record-id').value='';document.getElementById('form-title').textContent='Add record'}function editRecord(row){document.getElementById('record-id').value=row.id;<?php foreach ($fields as $field => $label): ?>document.getElementById('field-<?= esc($field) ?>').value=row['<?= esc($field) ?>']??'';<?php endforeach ?>document.getElementById('form-title').textContent='Edit record #'+row.id;window.scrollTo({top:0,behavior:'smooth'})}</script>
<?php $content = ob_get_clean(); echo view('admin/shell', ['title' => $title, 'content' => $content]); ?>
